scripts:
const root = document.documentElement;
document.getElementById('themeBtn').addEventListener('click', () => {
  if (root.dataset.theme === 'night') delete root.dataset.theme; else root.dataset.theme = 'night';
});
const q = new URLSearchParams(location.search);
if (q.get('theme') === 'night') root.dataset.theme = 'night';

(() => {
  const maps = [...document.querySelectorAll('.rm')];
  const chips = [...document.querySelectorAll('.rmap-chip')];
  const rows = [...document.querySelectorAll('.route-days tbody tr')];
  const has = (el, attr, d) => (el.getAttribute(attr) || '').split(' ').includes(d);
  function show(d) {
    maps.forEach((svg) => {
      svg.classList.toggle('has-on', d !== 'all');
      svg.querySelectorAll('.rm-leg').forEach((g) => g.classList.toggle('on', g.dataset.day === d));
      svg.querySelectorAll('.rm-stop').forEach((g) => {
        g.classList.toggle('on', has(g, 'data-day', d));
        g.classList.toggle('from', has(g, 'data-from', d));
        g.classList.toggle('from-name', has(g, 'data-from-name', d));
      });
    });
    chips.forEach((c) => c.setAttribute('aria-pressed', String(c.dataset.day === d)));
    rows.forEach((r) => r.classList.toggle('on', r.dataset.day === d));
  }
  chips.forEach((c) => c.addEventListener('click', () => show(c.dataset.day)));
  rows.forEach((r) => r.addEventListener('click', () => show(r.dataset.day === document.querySelector('.rmap-chip[aria-pressed="true"]')?.dataset.day ? 'all' : r.dataset.day)));
  const q = new URLSearchParams(location.search).get('day');
  if (q) show(q);
})();

(() => {
  const gs = new URLSearchParams(location.search).get('gscroll');
  document.querySelectorAll('.gallery-wrap').forEach((wrap, i) => {
    const g = wrap.querySelector('.gallery'), btns = [...wrap.querySelectorAll('.gallery-nav .round')];
    const sync = () => { btns[0].disabled = g.scrollLeft <= 4; btns[1].disabled = g.scrollLeft + g.clientWidth >= g.scrollWidth - 4; };
    btns.forEach((b) => b.addEventListener('click', () => g.scrollBy({ left: Number(b.dataset.dir) * g.clientWidth * 0.7, behavior: 'smooth' })));
    g.addEventListener('scroll', sync, { passive: true }); addEventListener('resize', sync); sync();
    if (gs && i === 0) { g.scrollLeft = Number(gs); sync(); }
  });
})();
